/// <summary>
/// The <c>ISDAppIntgDMFExecutionHistoryImportViewModel</c> class contains shared code used across the DMF execution history forms.
/// </summary>
public class ISDAppIntgDMFExecutionHistoryImportViewModel
{
    private ISDAppIntgDMFExecutionHistoryStatusFilterOptions    exeHistoryStatusFilter;
    private ISDAppIntgDMFExecutionHistoryFilterProvider         workspaceForm;
    private ISDAppIntgDMFExecutionHistoryImportFilterForm       taskForm;

}

Method.Source:
/// <summary>
/// Creates a new instance of the <c>ISDAppIntgDMFExecutionHistoryImportViewModel</c> class.
/// </summary>
/// <param name = "_dmfTaskForm">An instance of a DMF execution history form.</param>
/// <returns>A new instance of the <c>ISDAppIntgDMFExecutionHistoryImportViewModel</c> class.</returns>
public static ISDAppIntgDMFExecutionHistoryImportViewModel construct(
    ISDAppIntgDMFExecutionHistoryImportFilterForm _dmfTaskForm,
    ISDAppIntgDMFExecutionHistoryFilterProvider _dmfWorkspaceForm)
{
    ISDAppIntgDMFExecutionHistoryImportViewModel viewModel = new ISDAppIntgDMFExecutionHistoryImportViewModel();
    viewModel.initialize(_dmfTaskForm, _dmfWorkspaceForm);

    return viewModel;
}

/// <summary>
/// Initialize form datasources
/// </summary>
/// <param name = "_dmfTaskForm">Calling form</param>
/// <param name = "_dmfWorkspaceForm">Calling workspace</param>
private void initialize(ISDAppIntgDMFExecutionHistoryImportFilterForm _dmfTaskForm, ISDAppIntgDMFExecutionHistoryFilterProvider _dmfWorkspaceForm)
{
    Args taskFormArgs = _dmfTaskForm.getCallingArgs();
    boolean skipEventHandler = taskFormArgs.name() == formStr(ISDAppIntgDMFExecutionHistoryImportListForm);

    taskForm        = _dmfTaskForm;
    workspaceForm   = _dmfWorkspaceForm;

    if (taskForm == null || workspaceForm == null)
    {
        throw error(Error::wrongUseOfFunction(funcName()));
    }

    exeHistoryStatusFilter = taskFormArgs.parmEnum();

    this.initDefinitionGroupExecutionDS(taskForm.getDMFDefinitionGroupExecutionDS());
    this.initChildEntityExecutionDS(taskForm.getChildEntityExecutionDS());

    if (workspaceForm.getDefGroupNameFilterControl() != null)
    {
        if (!skipEventHandler)
        {
            workspaceForm.getDefGroupNameFilterControl().OnModified += eventhandler(this.onDefGroupNameFilterControlModified);
        }
        this.applyDefinitionGroupFilter(workspaceForm.getDefGroupNameFilterValue());
    }

    if (workspaceForm.getDefGroupDateFilterControl() != null)
    {
        if (!skipEventHandler)
        {
            workspaceForm.getDefGroupDateFilterControl().OnModified += eventhandler(this.onDefGroupDateFilterControlModified);
        }
        this.applyDateSelectionFilter(workspaceForm.getDefGroupDateFilterValue());
    }
}

/// <summary>
/// Form control modified
/// </summary>
/// <param name = "_formControl">Calling control</param>
/// <param name = "_eventArgs">Form control event args</param>
private void onDefGroupNameFilterControlModified(FormControl _formControl, FormControlEventArgs _eventArgs)
{
    FormStringControl defGroupNameControl = _formControl as FormStringControl;

    if (defGroupNameControl == null)
    {
        return;
    }

    this.applyDefinitionGroupFilter(defGroupNameControl.valueStr());
}

/// <summary>
/// Form control modified
/// </summary>
/// <param name = "_formControl">Calling control</param>
/// <param name = "_eventArgs">Form control event args</param>
private void onDefGroupDateFilterControlModified(FormControl _formControl, FormControlEventArgs _eventArgs)
{
    FormComboBoxControl defGroupDateFilterControl = _formControl as FormComboBoxControl;

    if (defGroupDateFilterControl == null)
    {
        return;
    }

    this.applyDateSelectionFilter(defGroupDateFilterControl.selection());
}

/// <summary>
/// Apply filter by definition group name
/// </summary>
/// <param name = "_definitionGroupName">Definition group name</param>
private void applyDefinitionGroupFilter(DMFDefinitionGroupName _definitionGroupName)
{
    FormDataSource definitionGroupExecutionDataSource = taskForm.getDMFDefinitionGroupExecutionDS();

    if (definitionGroupExecutionDataSource !=null)
    {
        QueryBuildRange queryBuildRange = SysQuery::findOrCreateRange(definitionGroupExecutionDataSource.queryBuildDataSource(), fieldNum(DMFDefinitionGroupExecution, DefinitionGroup));

        if (_definitionGroupName == '')
        {
            queryBuildRange.value(SysQuery::valueUnlimited());
        }
        else
        {
            queryBuildRange.value(_definitionGroupName);
        }

        definitionGroupExecutionDataSource.executeQuery();
    }
}

/// <summary>
/// Apply filter by date range
/// </summary>
/// <param name = "_dateFilterOptions">Date range selection</param>
private void applyDateSelectionFilter(DMFExecutionHistoryDateFilterOptions _dateFilterOptions)
{
    FormDataSource definitionGroupExecutionDataSource = taskForm.getDMFDefinitionGroupExecutionDS();
    FormDataSource childEntityExecutionDataSource = taskForm.getChildEntityExecutionDS();

    if (definitionGroupExecutionDataSource !=null && childEntityExecutionDataSource != null)
    {

        DMFFormUtil::buildRangeByExecutionHistoryDateFilter(definitionGroupExecutionDataSource.queryBuildDataSource(), _dateFilterOptions);

        definitionGroupExecutionDataSource.executeQuery();
        childEntityExecutionDataSource.executeQuery();
    }
}

/// <summary>
/// Initialize form datasource
/// </summary>
/// <param name = "_definitionGroupExecutionDS">Form data source</param>
private void initDefinitionGroupExecutionDS(FormDataSource _definitionGroupExecutionDS)
{
    if (_definitionGroupExecutionDS != null)
    {
        _definitionGroupExecutionDS.queryBuildDataSource().addOrderByField(fieldNum(DMFDefinitionGroupExecution, CreatedDateTime), SortOrder::Descending);

        QueryBuildDataSource qbd = _definitionGroupExecutionDS.query().dataSourceTable(tableNum(DMFDefinitionGroupExecution));

        QueryBuildDataSource entityDs = qbd.addDataSource(tableNum(DMFEntity));
        entityDs.joinMode(JoinMode::ExistsJoin);
        entityDs.relations(true);
        entityDs.addRange(fieldNum(DMFEntity,ParentEntityName)).value(SysQuery::valueEmptyString());

        QueryBuildDataSource definitionGroupDs = qbd.addDataSource(tableNum(DMFDefinitionGroup));
        definitionGroupDs.joinMode(JoinMode::ExistsJoin);
        definitionGroupDs.relations(true);
        definitionGroupDs.addRange(fieldNum(DMFDefinitionGroup, OperationType)).value(queryValue(DMFOperationType::Import));
        definitionGroupDs.addRange(fieldNum(DMFDefinitionGroup, ProjectCategory)).value(queryValue(DMFProjectCategory::Integration));

        switch(exeHistoryStatusFilter)
        {
            case ISDAppIntgDMFExecutionHistoryStatusFilterOptions::AllError:

                _definitionGroupExecutionDS.queryBuildDataSource().addRange(fieldNum(DMFDefinitionGroupExecution, RecId)).value(strFmt('((%1.%2 == 3) || (%1.%3 == 3))', _definitionGroupExecutionDS.queryBuildDataSource().name(), fieldStr(DMFDefinitionGroupExecution, StagingStatus), fieldStr(DMFDefinitionGroupExecution, TargetStatus)));
                break;

            case ISDAppIntgDMFExecutionHistoryStatusFilterOptions::Ended:

                _definitionGroupExecutionDS.queryBuildDataSource().addRange(fieldNum(DMFDefinitionGroupExecution, RecId)).value(strFmt('((%1.%2 == 4) && (%1.%3 == 4))', _definitionGroupExecutionDS.queryBuildDataSource().name(), fieldStr(DMFDefinitionGroupExecution, StagingStatus), fieldStr(DMFDefinitionGroupExecution, TargetStatus)));
                break;

            case ISDAppIntgDMFExecutionHistoryStatusFilterOptions::StagingError:

                _definitionGroupExecutionDS.queryBuildDataSource().addRange(fieldNum(DMFDefinitionGroupExecution, RecId)).value(strFmt('((%1.%2 == 3))', _definitionGroupExecutionDS.queryBuildDataSource().name(), fieldStr(DMFDefinitionGroupExecution, StagingStatus)));
                break;

            case ISDAppIntgDMFExecutionHistoryStatusFilterOptions::TargetError:

                _definitionGroupExecutionDS.queryBuildDataSource().addRange(fieldNum(DMFDefinitionGroupExecution, RecId)).value(strFmt('((%1.%2 == 3) || (%1.%3 > 0) || (%1.%3 > 0))', _definitionGroupExecutionDS.queryBuildDataSource().name(),
                                                                                                                                                                                        fieldStr(DMFDefinitionGroupExecution, TargetStatus),
                                                                                                                                                                                        fieldStr(DMFDefinitionGroupExecution, StagingErrorCount),
                                                                                                                                                                                        fieldStr(DMFDefinitionGroupExecution, TargetErrorCount)));
                break;

            case ISDAppIntgDMFExecutionHistoryStatusFilterOptions::All:

                _definitionGroupExecutionDS.queryBuildDataSource().clearRange(fieldNum(DMFDefinitionGroupExecution, StagingErrorCount));
                _definitionGroupExecutionDS.queryBuildDataSource().clearRange(fieldNum(DMFDefinitionGroupExecution, StagingStatus));
                _definitionGroupExecutionDS.queryBuildDataSource().clearRange(fieldNum(DMFDefinitionGroupExecution, TargetErrorCount));
                _definitionGroupExecutionDS.queryBuildDataSource().clearRange(fieldNum(DMFDefinitionGroupExecution, TargetStatus));
                break;
        }
    }
}

/// <summary>
/// Initialize form datasource
/// </summary>
/// <param name = "_definitionGroupExecutionDS">Form data source</param>
private void initChildEntityExecutionDS(FormDataSource _childEntityExecutionDS)
{
    if (_childEntityExecutionDS != null)
    {
        _childEntityExecutionDS.queryBuildDataSource().addOrderByField(fieldNum(DMFDefinitionGroupExecution, CreatedDateTime), SortOrder::Descending);

        QueryBuildDataSource qbd = _childEntityExecutionDS.query().dataSourceTable(tableNum(DMFDefinitionGroupExecution));

        QueryBuildDataSource entityDs = qbd.addDataSource(tableNum(DMFEntity));
        entityDs.joinMode(JoinMode::ExistsJoin);
        entityDs.relations(true);
        entityDs.addRange(fieldNum(DMFEntity,ParentEntityName)).value(SysQuery::valueNotEmptyString());
    }
}

/// <summary>
/// Initialize form datasource
/// </summary>
/// <param name = "_definitionGroupExecutionDS">Form data source</param>
private void initDMFExecutionDS(FormDataSource _executionDS)
{

}
